 StackPanel Group(string glyph,string text){
  string shortName=text switch{"Aparência e inicialização"=>"Aparência","Áreas da sua mesa"=>"Áreas","Sincronização com Google"=>"Google","Dados e backup"=>"Dados",_=>"Atalhos"};
  int index=sections.Count;var page=new StackPanel{Visibility=index==0?Visibility.Visible:Visibility.Collapsed};var heading=Visuals.Label(text,14);heading.FontWeight=FontWeights.SemiBold;heading.Margin=new Thickness(0,0,0,10);page.Children.Add(heading);body.Children.Add(page);
  var button=Visuals.TextButton(shortName,()=>SelectSection(index));button.Height=48;button.Margin=new Thickness(2,0,2,0);button.Padding=new Thickness(2);button.BorderThickness=new Thickness(0);button.ToolTip=text;
  var caption=new StackPanel();caption.Children.Add(new TextBlock{Text=glyph,FontFamily=new FontFamily("Segoe Fluent Icons"),FontSize=17,HorizontalAlignment=HorizontalAlignment.Center,Margin=new Thickness(0,0,0,3)});caption.Children.Add(new TextBlock{Text=shortName,FontSize=10,HorizontalAlignment=HorizontalAlignment.Center});button.Content=caption;System.Windows.Automation.AutomationProperties.SetName(button,"Configurações: "+shortName);sections.Add((button,page));navigation.Children.Add(button);return page;
