 Button ActionButton(string glyph,string text,Action action){var button=Visuals.TextButton(text,action);button.MinHeight=button.Height=32;button.Margin=new Thickness(0,3,0,3);button.Padding=new Thickness(10,4,10,4);var row=new StackPanel{Orientation=Orientation.Horizontal};row.Children.Add(new TextBlock{Text=glyph,FontFamily=new FontFamily("Segoe Fluent Icons"),FontSize=14,Width=24,VerticalAlignment=VerticalAlignment.Center});row.Children.Add(new TextBlock{Text=text,FontSize=12,VerticalAlignment=VerticalAlignment.Center});button.Content=row;actionButtons.Add(button);return button;}
 static void SetActionLabel(Button button,string text){if(button.Content is StackPanel row&&row.Children[row.Children.Count-1] is TextBlock label)label.Text=text;System.Windows.Automation.AutomationProperties.SetName(button,text);}
 internal int SectionCount=>sections.Count;
 internal void SelectSection(int index){if(index<0||index>=sections.Count)return;selectedSection=index;for(int i=0;i<sections.Count;i++)sections[i].Page.Visibility=i==index?Visibility.Visible:Visibility.Collapsed;RefreshNavigation();UpdateLayout();}
 void RefreshNavigation(){foreach(var (button,page) in sections){bool selected=page.Visibility==Visibility.Visible;button.Background=selected?Visuals.Brush("#557F7FFF"):Brushes.Transparent;System.Windows.Automation.AutomationProperties.SetHelpText(button,selected?"Selecionado":"");}}
 internal bool SectionsFit(){int previous=selectedSection;bool fits=true;for(int i=0;i<sections.Count;i++){SelectSection(i);foreach(var item in Descendants<FrameworkElement>(sections[i].Page).Where(e=>e.IsVisible&&(e is Button or TextBox or Slider or CheckBox))){var point=item.TranslatePoint(new Point(),this);var corner=item.TranslatePoint(new Point(item.ActualWidth,item.ActualHeight),this);fits&=point.X>=0&&point.Y>=0&&corner.X<=ActualWidth+1&&corner.Y<=ActualHeight+1;}fits&=!Descendants<ScrollViewer>(surface).Any(scroll=>scroll.ComputedVerticalScrollBarVisibility==Visibility.Visible||scroll.ScrollableHeight>1);}SelectSection(previous);return fits;}

 public void ApplyTheme(){updatingOpacity=true;opacity.Value=app.Store.Book.BackgroundOpacity;opacityValue.Text=app.Store.Book.BackgroundOpacity+"%";updatingOpacity=false;SuitePanels.Theme(this,surface,app.Store.Book.Theme);foreach(var button in themes){bool selected=(string)button.Tag==app.Store.Book.Theme;button.Background=selected?Visuals.Brush("#557F7FFF"):Visuals.Brush(Visuals.Dark(app.Store.Book.Theme)?"#3B3E47":"#E4E6ED");System.Windows.Automation.AutomationProperties.SetHelpText(button,selected?"Selecionado":"");}foreach(var button in actionButtons)button.Background=SystemParameters.HighContrast?SystemColors.ControlBrush:Visuals.Brush(Visuals.Dark(app.Store.Book.Theme)?"#3B3E47":"#E4E6ED");RefreshNavigation();foreach(var button in Descendants<Button>(surface))button.Foreground=Foreground;}
 static System.Collections.Generic.IEnumerable<T> Descendants<T>(DependencyObject p) where T:DependencyObject{for(int i=0;i<VisualTreeHelper.GetChildrenCount(p);i++){var c=VisualTreeHelper.GetChild(p,i);if(c is T value)yield return value;foreach(var child in Descendants<T>(c))yield return child;}}
 bool SaveOpacity(){opacitySave.Stop();if(!pendingOpacity)return true;try{app.Store.Save();pendingOpacity=false;return true;}catch(Exception e){Visuals.Error("Não foi possível salvar a opacidade. Tente novamente antes de fechar.\n"+e.Message);return false;}}
 public void Present(){Show();Activate();if(SystemParameters.ClientAreaAnimation&&!SystemParameters.HighContrast)animation=new WindowRevealAnimation(this,true,()=>{});}
 public void Dismiss(bool animate=true){if(!SaveOpacity())return;animation?.Dispose();void Finish(){closing=true;Close();}if(animate&&IsVisible&&SystemParameters.ClientAreaAnimation&&!SystemParameters.HighContrast)animation=new WindowRevealAnimation(this,false,Finish);else Finish();}
